SELECT COALESCE(MAX(b.id), 0) + 1, 'Black Friday Price List: Up to 28% Off Cartons, 1 to 30 November', 'black-friday-2026-price-list', '<p>Black Friday runs all month at Xpel Beauty NG. From <strong>1 to 30 November 2026</strong>, 22 lines across XBC skincare and XHC hair care carry promo carton prices, with discounts from 5% to 28%.</p>
<p>The deepest cuts are on the XHC heat defence sprays (28% off), the XBC Hemp Face Mask (27%) and the XBC Charcoal Detox Facial Mask (23%). The XHC Argan Oil, Rosemary &amp; Mint and Aloe Vera leave-in conditioners are 20% off.</p>
<p>Prices are per carton (CTN). The unit price is the carton price divided by the pieces in the carton. All prices are in naira.</p>
<h2>Skincare</h2>
<table><thead><tr><th>Product</th><th>Pcs/CTN</th><th>Carton price</th><th>Promo carton</th><th>Discount</th><th>Unit price</th><th>Promo unit</th></tr></thead><tbody><tr><td>XBC Banana Face &amp; Body Scrub 250ml</td><td>12</td><td><s>₦32,000</s></td><td><strong>₦27,000</strong></td><td>16%</td><td>₦2,666.67</td><td><strong>₦2,250</strong></td></tr><tr><td>Osiris Avisé Recovery Oil 100ml</td><td>12</td><td><s>₦30,000</s></td><td><strong>₦25,000</strong></td><td>17%</td><td>₦2,500</td><td><strong>₦2,083.33</strong></td></tr><tr><td>XBC Hemp Face Mask</td><td>24</td><td><s>₦35,000</s></td><td><strong>₦25,550</strong></td><td>27%</td><td>₦1,458.33</td><td><strong>₦1,064.58</strong></td></tr><tr><td>XBC Charcoal Detox Facial Mask</td><td>24</td><td><s>₦45,000</s></td><td><strong>₦34,650</strong></td><td>23%</td><td>₦1,875</td><td><strong>₦1,443.75</strong></td></tr><tr><td>XBC Papaya Hydrating Face Mask</td><td>24</td><td><s>₦26,000</s></td><td><strong>₦21,840</strong></td><td>16%</td><td>₦1,083.33</td><td><strong>₦910</strong></td></tr><tr><td>XBC Aloe Vera Facial Mask</td><td>24</td><td><s>₦26,000</s></td><td><strong>₦21,840</strong></td><td>16%</td><td>₦1,083.33</td><td><strong>₦910</strong></td></tr><tr><td>XBC Vitamin C Revitalising Face Mask</td><td>24</td><td><s>₦26,000</s></td><td><strong>₦21,840</strong></td><td>16%</td><td>₦1,083.33</td><td><strong>₦910</strong></td></tr><tr><td>XBC Tea Tree Cleansing Facial Scrub 250ml</td><td>12</td><td><s>₦35,000</s></td><td><strong>₦29,750</strong></td><td>15%</td><td>₦2,916.67</td><td><strong>₦2,479.17</strong></td></tr><tr><td>XBC Tea Tree Facial Toner 200ml</td><td>12</td><td><s>₦36,000</s></td><td><strong>₦30,600</strong></td><td>15%</td><td>₦3,000</td><td><strong>₦2,550</strong></td></tr><tr><td>XBC Tea Tree Foaming Face Wash 200ml</td><td>12</td><td><s>₦36,000</s></td><td><strong>₦30,600</strong></td><td>15%</td><td>₦3,000</td><td><strong>₦2,550</strong></td></tr><tr><td>Tea Tree Cleansing Facial Wipes Twin Pack</td><td>12</td><td><s>₦36,000</s></td><td><strong>₦30,600</strong></td><td>15%</td><td>₦3,000</td><td><strong>₦2,550</strong></td></tr><tr><td>XBC Vitamin C Foaming Face Wash 200ml</td><td>12</td><td><s>₦39,000</s></td><td><strong>₦35,100</strong></td><td>10%</td><td>₦3,250</td><td><strong>₦2,925</strong></td></tr><tr><td>XBC Vitamin C Face Serum 30ml</td><td>24</td><td><s>₦84,000</s></td><td><strong>₦79,800</strong></td><td>5%</td><td>₦3,500</td><td><strong>₦3,325</strong></td></tr></tbody></table>
<h2>Hair care</h2>
<table><thead><tr><th>Product</th><th>Pcs/CTN</th><th>Carton price</th><th>Promo carton</th><th>Discount</th><th>Unit price</th><th>Promo unit</th></tr></thead><tbody><tr><td>XHC Argan Oil Leave-In Conditioner 250ml</td><td>12</td><td><s>₦30,000</s></td><td><strong>₦24,000</strong></td><td>20%</td><td>₦2,500</td><td><strong>₦2,000</strong></td></tr><tr><td>XHC Rosemary &amp; Mint Leave-In Conditioner 250ml</td><td>12</td><td><s>₦30,000</s></td><td><strong>₦24,000</strong></td><td>20%</td><td>₦2,500</td><td><strong>₦2,000</strong></td></tr><tr><td>XHC Avocado &amp; Almond Heat Defence Leave-In Spray 150ml</td><td>12</td><td><s>₦25,000</s></td><td><strong>₦18,000</strong></td><td>28%</td><td>₦2,083.33</td><td><strong>₦1,500</strong></td></tr><tr><td>XHC Black Castor Oil &amp; Avocado Heat Defence Leave-In Spray 150ml</td><td>12</td><td><s>₦25,000</s></td><td><strong>₦18,000</strong></td><td>28%</td><td>₦2,083.33</td><td><strong>₦1,500</strong></td></tr><tr><td>XHC Aloe Vera Heat Defence Spray 150ml</td><td>12</td><td><s>₦25,000</s></td><td><strong>₦18,000</strong></td><td>28%</td><td>₦2,083.33</td><td><strong>₦1,500</strong></td></tr><tr><td>XHC Aloe Vera Leave-In Conditioner</td><td>12</td><td><s>₦30,000</s></td><td><strong>₦24,000</strong></td><td>20%</td><td>₦2,500</td><td><strong>₦2,000</strong></td></tr><tr><td>XHC Black Castor Oil &amp; Avocado Leave-In Conditioner 250ml</td><td>12</td><td><s>₦31,000</s></td><td><strong>₦27,900</strong></td><td>10%</td><td>₦2,583.33</td><td><strong>₦2,325</strong></td></tr><tr><td>XHC Black Castor Oil &amp; Avocado Hair &amp; Scalp Treatment 150ml</td><td>12</td><td><s>₦31,000</s></td><td><strong>₦27,900</strong></td><td>10%</td><td>₦2,583.33</td><td><strong>₦2,325</strong></td></tr><tr><td>XHC Black Castor Oil &amp; Avocado Shampoo 400ml</td><td>12</td><td><s>₦31,000</s></td><td><strong>₦27,900</strong></td><td>10%</td><td>₦2,583.33</td><td><strong>₦2,325</strong></td></tr></tbody></table>
